effect.shader:
float hash1(float x) {
    return fract(sin(x * 127.1 + float(seed) * 13.7) * 43758.5453);
}

float hash2(vec2 c) {
    c += vec2(float(seed) * 13.7);
    return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}

float ruido2(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 s = f * f * (3.0 - 2.0 * f);
    float a = hash2(i);
    float b = hash2(i + vec2(1.0, 0.0));
    float c = hash2(i + vec2(0.0, 1.0));
    float d = hash2(i + vec2(1.0, 1.0));
    return mix(mix(a, b, s.x), mix(c, d, s.x), s.y);
}

float fbm(vec2 p) {
    float soma = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 4; i++) {
        soma += ruido2(p) * amp;
        p *= 2.0;
        amp *= 0.5;
    }
    return soma;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    // A queima anda de ponto em ponto — cada "estação" dura ~3 segundos.
    float estacao = floor(acTime * speed * 0.3);
    vec2 centro = vec2(hash1(estacao + 1.3), hash1(estacao + 7.7));
    centro = vec2(centro.x * acAspect, centro.y);

    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y);

    // Ruído distorce a borda: faz o círculo ter contorno irregular.
    float ruido = fbm(p * 8.0 + estacao * 13.0);
    float distorcao = (ruido - 0.5) * raggedness * size;

    float d = length(p - centro) + distorcao;

    // O miolo: tudo que está dentro do raio × 0.4.
    float miolo = 1.0 - smoothstep(size * 0.3, size * 0.5, d);
    // O anel: entre 0.4 e 1.0 do raio.
    float anel = (1.0 - smoothstep(size * 0.8, size * 1.1, d)) * smoothstep(size * 0.3, size * 0.6, d);

    // Fade na borda do take (o furo não cresce indefinidamente).
    float janela = 1.0 - smoothstep(size, size * 1.1, d);
    miolo *= janela;
    anel *= janela;

    vec3 cor = original.rgb;
    // Anel: escurece pelo tom carbonizado.
    cor = mix(cor, burnRing.rgb, anel * burnRing.a * intensity * 0.8);
    // Miolo: adiciona luz amarela em screen (a brasa).
    vec3 brasa = burnCore.rgb * miolo * intensity * burnCore.a;
    cor = 1.0 - (1.0 - cor) * (1.0 - brasa);

    fragColor = vec4(cor, original.a);
}
